```json
{
  "schemaVersion": "0.3.0-alpha",
  "programId": "streaking-three-cultures",
  "name": "Streaking Three Cultures onto Selective Media",
  "description": "Three overnight broths streaked for single colonies on selective agar, incubated at 37 °C and read the next morning. Supervisor approval gates subculture and purity plate streak.",
  "environmentType": "laboratory",
  "actors": 1,
  "tracks": [
    {
      "trackId": "prep",
      "name": "Bench Prep",
      "steps": [
        {
          "stepId": "wipe_bench",
          "name": "Wipe bench with 70% ethanol and light burner",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "label_plates",
          "name": "Label three selective plates",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wipe_bench" }
        }
      ]
    },
    {
      "trackId": "streaking",
      "name": "Streaking Three Isolates",
      "steps": [
        {
          "stepId": "streak",
          "name": "Streak isolate for single colonies",
          "task": "loop_station",
          "duration": { "type": "fixed", "seconds": 600 },
          "replicates": { "count": 3, "mode": "serial" },
          "startTrigger": { "type": "afterStep", "stepId": "label_plates" }
        }
      ]
    },
    {
      "trackId": "incubation_main",
      "name": "Incubation: Plates 1 & 2",
      "steps": [
        {
          "stepId": "invert_and_incubate_main",
          "name": "Invert plates 1 and 2, place on incubator shelf",
          "task": "incubator_shelf",
          "duration": { "type": "fixed", "seconds": 72000 },
          "startTrigger": { "type": "afterStep", "stepId": "streak", "instances": "each" }
        }
      ]
    },
    {
      "trackId": "plate3_holding",
      "name": "Plate 3: Room Temperature Hold then Incubation",
      "steps": [
        {
          "stepId": "hold_plate3",
          "name": "Hold plate 3 at room temperature on bench",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 0 },
          "startTrigger": { "type": "afterStep", "stepId": "streak", "instances": "each" }
        },
        {
          "stepId": "incubate_plate3",
          "name": "Incubate plate 3 at 37 °C for 6 hours",
          "task": "incubator_shelf",
          "duration": { "type": "fixed", "seconds": 21600 },
          "startTrigger": { "type": "afterStep", "stepId": "invert_and_incubate_main", "instances": "all" }
        }
      ]
    },
    {
      "trackId": "reading",
      "name": "Reading Plates",
      "steps": [
        {
          "stepId": "read_plates",
          "name": "Read plate: count colonies, note color, record selective growth",
          "task": "microscope",
          "duration": { "type": "fixed", "seconds": 900 },
          "replicates": { "count": 3, "mode": "serial" },
          "startTrigger": {
            "type": "compound",
            "logic": "all",
            "triggers": [
              { "type": "afterStep", "stepId": "invert_and_incubate_main", "instances": "all" },
              { "type": "afterStep", "stepId": "incubate_plate3" }
            ]
          }
        }
      ]
    },
    {
      "trackId": "subculture",
      "name": "Subculture: Pick Colonies from Plates 1 & 2",
      "steps": [
        {
          "stepId": "supervisor_approval",
          "name": "Supervisor reviews and signs off readings",
          "task": "supervisor",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "read_plates", "instances": "all" }
        },
        {
          "stepId": "pick_colonies",
          "name": "Pick single well-separated colony into fresh broth",
          "task": "loop_station",
          "duration": { "type": "fixed", "seconds": 600 },
          "replicates": { "count": 2, "mode": "serial" },
          "startTrigger": { "type": "afterStep", "stepId": "supervisor_approval" }
        }
      ]
    },
    {
      "trackId": "purity_plate",
      "name": "Purity Plate Subculture",
      "steps": [
        {
          "stepId": "streak_purity",
          "name": "Streak purity plate",
          "task": "loop_station",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "supervisor_approval" }
        },
        {
          "stepId": "incubate_purity",
          "name": "Incubate purity plate at 37 °C for 8 hours",
          "task": "incubator_shelf",
          "duration": { "type": "fixed", "seconds": 28800 },
          "startTrigger": { "type": "afterStep", "stepId": "streak_purity" }
        }
      ]
    },
    {
      "trackId": "staining",
      "name": "Gram Staining (Plates 1 & 2 colonies)",
      "steps": [
        {
          "stepId": "make_smear",
          "name": "Make smear and heat-fix",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "pick_colonies", "instances": "each" }
        },
        {
          "stepId": "gram_stain",
          "name": "Gram stain: crystal violet, iodine, decolourise, safranin",
          "task": "staining_rack",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "make_smear", "instances": "each" }
        },
        {
          "stepId": "read_stain",
          "name": "Read stain under oil immersion, record morphology",
          "task": "microscope",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "gram_stain", "instances": "each" }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "bench", "maxConcurrent": 1 },
    { "task": "loop_station", "maxConcurrent": 1 },
    { "task": "incubator_shelf", "maxConcurrent": 1 },
    { "task": "microscope", "maxConcurrent": 1 },
    { "task": "staining_rack", "maxConcurrent": 1 },
    { "task": "supervisor", "maxConcurrent": 1 }
  ],
  "metadata": {
    "sourceText": "Streaking Three Cultures onto Selective Media",
    "technique": "Microbiological streaking for single colonies",
    "incubationTemperature": "37 °C",
    "overnight": "16–20 hours"
  }
}
